<?php foreach ($rows as $o): ?><tr><td class="mono"><a class="link" href="/paraggelia/<?= e($o['number']) ?>"><?= e($o['number']) ?></a></td><td><?= e(date_gr($o['created_at'], true)) ?></td><td><?= e($o['name']) ?><br><span class="small muted"><?= e($o['email']) ?></span></td><td class="tnum"><?= money((int)$o['total_cents']) ?></td><td class="tnum"><?= money((int)$o['platform_fee_cents']) ?></td><td><span class="badge badge-<?= e($o['status']) ?>"><?= e($o['status']) ?></span></td></tr><?php endforeach ?>
